SELECT * FROM spd_material
WHERE del_flag = #{delFlag}

    AND material_name LIKE CONCAT('%', #{query.materialName}, '%')


    AND material_code LIKE CONCAT('%', #{query.materialCode}, '%')


    AND manufacturer LIKE CONCAT('%', #{query.manufacturer}, '%')


    AND supplier_name LIKE CONCAT('%', #{query.supplierName}, '%')


    AND is_group_buy = #{query.isGroupBuy}


    AND category = #{query.category}


    AND material_status = #{query.materialStatus}

ORDER BY create_time DESC

SELECT * FROM spd_material
WHERE material_name = #{materialName}
AND manufacturer = #{manufacturer}
AND del_flag = #{delFlag}

    AND id != #{id}

LIMIT 1

SELECT * FROM spd_material
WHERE material_id = #{materialId}
AND del_flag = #{delFlag}
LIMIT 1
